/* play/atari2600/web/render.js — the TIA raster onto a canvas.
 *
 * SITE-OWNED. See web/core.js's header for why this layer is not vendored.
 *
 * WHAT THE CORE HANDS OVER, from the core interface "Video": 320 rows of 160
 * bytes, every row the beam drew between one VSYNC and the next. Each byte is
 * the TIA colour value with bit 0 always 0; turning it into RGB needs a
 * palette the hardware does not contain, which is web/palette.js — generated by
 * the palette generator and vendored here byte-identical.
 *
 * TWO THINGS THE DOCUMENT SAYS THAT THIS FILE OBEYS AND THAT ARE EASY TO MISS:
 *
 *   1. "A television would show only part of it." The raster is the whole
 *      field including blanking; the visible window is rows 23..250 for NTSC
 *      and 32..305 for PAL/SECAM. Drawing all 320 rows puts a thick black band
 *      above and below the picture INSIDE the television's aperture, which on
 *      this site would read as the artwork being misaligned rather than as the
 *      renderer showing blanking. WINDOW lives in core.js beside the region
 *      constants it is indexed by.
 *
 *   2. "Present the pixels twice as wide as they are tall." 160 across at 2:1
 *      is the 320-equivalent width a set produced, and 320x228 is 1.40 — close
 *      to the 4:3 the aperture measures (1.3553 on this photograph). The canvas
 *      is therefore sized 320 x window.h and the aperture stretches it the rest
 *      of the way, which is correct rather than a stretch for the reason
 *      atari-screen.css gives at .atari-screen: these are non-square pixels and
 *      the aperture is the shape the hardware actually made on glass.
 *
 * WHY AN OFFSCREEN CANVAS AND A drawImage, rather than putImageData straight
 * onto the visible one: putImageData does not scale, so the 2:1 widening has to
 * be a draw. The offscreen is 160 wide — the raster's own width — so exactly
 * one scale happens and it is the browser's, with smoothing off.
 */
import { RASTER_W, RASTER_H, WINDOW } from './core.js';
import * as PALETTE from './palette.js';

export const PALETTE_FOR_REGION = { 0: 'NTSC', 1: 'PAL', 2: 'SECAM' };

export class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.off = document.createElement('canvas');
    this.off.width = RASTER_W;
    this.off.height = RASTER_H;
    this.offCtx = this.off.getContext('2d', { alpha: false });
    this.img = this.offCtx.createImageData(RASTER_W, RASTER_H);
    /* One Uint32 per pixel so a palette entry becomes one store rather than
     * four. The byte order below is little-endian ABGR, which is what a
     * Uint32Array view of RGBA bytes is on every platform a browser runs on. */
    this.px = new Uint32Array(this.img.data.buffer);
    this.region = 0;
    this.pal = PALETTE.NTSC;
    this.lastLines = 0;
  }

  setRegion(r) {
    this.region = r | 0;
    this.pal = PALETTE[PALETTE_FOR_REGION[this.region]] || PALETTE.NTSC;
    const win = WINDOW[this.region];
    /* The canvas is resized to the WINDOW, not to the raster. Doing it here
     * rather than every frame matters: assigning to canvas.width clears the
     * canvas and reallocates its backing store, so doing it per frame is both
     * a flash and a per-frame allocation. */
    this.canvas.width = RASTER_W * 2;
    this.canvas.height = win.h;
    this.ctx.imageSmoothingEnabled = false;
  }

  /* `raster` is the Uint8Array core.raster() returns. It is a view onto wasm
   * memory and must not be retained past this call. */
  draw(raster) {
    const win = WINDOW[this.region];
    const pal = this.pal;
    const px = this.px;
    for (let i = win.y * RASTER_W, n = (win.y + win.h) * RASTER_W; i < n; i++) {
      const c = pal[raster[i]];
      /* 0xRRGGBB -> 0xFFBBGGRR. */
      px[i] = 0xFF000000 | ((c & 0xFF) << 16) | (c & 0xFF00) | ((c >> 16) & 0xFF);
    }
    this.offCtx.putImageData(this.img, 0, 0, 0, win.y, RASTER_W, win.h);
    /* imageSmoothingEnabled is re-asserted because a canvas resize resets it
     * and the resize path is not the only one that can reach here. */
    this.ctx.imageSmoothingEnabled = false;
    this.ctx.drawImage(this.off, 0, win.y, RASTER_W, win.h,
                       0, 0, this.canvas.width, this.canvas.height);
  }
}
